-- Corrige el yacimiento mal escrito: es "El tordillo" (t minuscula), no
-- "El Tordillo" -- por eso GSJ_CH, GSJ_WO, GSJ_CH_MODELO, GSJ_WO_MODELO y la
-- curva basica agregada de El Tordillo nunca se crearon (los inserts
-- anteriores hacian join contra un nombre que no existia y no insertaban
-- nada, sin tirar error). "Bloque G" no existe como yacimiento en esta base
-- -- se deja afuera GSJ_BLG/GSJ_BLG_MODELO hasta que se cargue ese
-- yacimiento.

insert into pozos_tipo (nombre, yacimiento_id, categoria)
select v.nombre, y.id, v.categoria
from (values
  ('GSJ_CH', 'El tordillo', 'basico'),
  ('GSJ_WO', 'El tordillo', 'workover'),
  ('GSJ_CH_MODELO', 'El tordillo', 'basico'),
  ('GSJ_WO_MODELO', 'El tordillo', 'workover')
) as v(nombre, yacimiento, categoria)
join yacimientos y on y.nombre = v.yacimiento
where not exists (select 1 from pozos_tipo pt where pt.nombre = v.nombre);

alter table pozos_tipo add column if not exists capex_default_usd numeric(14,2);
update pozos_tipo set capex_default_usd = 4550000 where nombre = 'GSJ_CH_MODELO';
update pozos_tipo set capex_default_usd = 556000 where nombre = 'GSJ_WO_MODELO';

